export const KARNATAKA_BOUNDS = {
  minLon: 74.085688,
  maxLon: 78.5858089032162,
  minLat: 11.594585,
  maxLat: 18.45426533168504,
} as const;

export function normalizeDistrictName(name: string): string {
  return (name || "").toLowerCase().replace(/[^a-z]/g, "");
}

const BY_KEY: Record<string, DistrictShape> = {};
for (const d of KARNATAKA_DISTRICTS) BY_KEY[normalizeDistrictName(d.name)] = d;

/**
 * Backend district names ("Bengaluru Urban", "Bengaluru Rural", "Mysuru")
 * do not always match the boundary set ("Bengaluru", "Bangalore"). Resolve
 * loosely: exact key first, then a prefix/contains match either way.
 */
export function findDistrict(name: string | null | undefined): DistrictShape | null {
  const key = normalizeDistrictName(name || "");
  if (!key) return null;
  if (BY_KEY[key]) return BY_KEY[key];
  for (const d of KARNATAKA_DISTRICTS) {
    const k = normalizeDistrictName(d.name);
    if (key.startsWith(k) || k.startsWith(key)) return d;
  }
  return null;
}
